class Solution:
    def numSplits(self, s: str) -> int:
        n = len(s)
        suf = [0] * (n + 1)
        seen = [False] * 26
        d = 0
        for i in range(n - 1, -1, -1):
            c = ord(s[i]) - 97
            if not seen[c]:
                seen[c] = True
                d += 1
            suf[i] = d
        left = [False] * 26
        d = 0
        ans = 0
        for i in range(n - 1):
            c = ord(s[i]) - 97
            if not left[c]:
                left[c] = True
                d += 1
            if d == suf[i + 1]:
                ans += 1
        return ans

