class Solution {
public:
    int numSplits(string s) {
        int n = s.size();
        vector<int> suf(n + 1, 0);
        bool seen[26] = {false};
        int d = 0;
        for (int i = n - 1; i >= 0; --i) {
            int c = s[i] - 'a';
            if (!seen[c]) { seen[c] = true; d++; }
            suf[i] = d;
        }
        bool left[26] = {false};
        d = 0;
        int ans = 0;
        for (int i = 0; i < n - 1; ++i) {
            int c = s[i] - 'a';
            if (!left[c]) { left[c] = true; d++; }
            if (d == suf[i + 1]) ans++;
        }
        return ans;
    }
};

