class Solution:
    def numSplits(self, s: str) -> int:
        fl = [0] * 26
        fr = [0] * 26
        dl = dr = 0
        for ch in s:
            c = ord(ch) - 97
            fr[c] += 1
            if fr[c] == 1:
                dr += 1
        ans = 0
        for ch in s[:-1]:
            c = ord(ch) - 97
            fl[c] += 1
            if fl[c] == 1:
                dl += 1
            fr[c] -= 1
            if fr[c] == 0:
                dr -= 1
            if dl == dr:
                ans += 1
        return ans

