class Solution {
public:
    int numSplits(string s) {
        int fl[26] = {0}, fr[26] = {0};
        int dl = 0, dr = 0;
        for (char ch : s) {
            int c = ch - 'a';
            if (fr[c]++ == 0) dr++;
        }
        int ans = 0;
        for (int i = 0; i + 1 < (int)s.size(); ++i) {
            int c = s[i] - 'a';
            if (fl[c]++ == 0) dl++;
            if (--fr[c] == 0) dr--;
            if (dl == dr) ans++;
        }
        return ans;
    }
};

