class Solution {
    public int numSplits(String s) {
        int[] fl = new int[26], fr = new int[26];
        int dl = 0, dr = 0;
        for (char ch : s.toCharArray()) {
            if (fr[ch - 'a']++ == 0) dr++;
        }
        int ans = 0;
        for (int i = 0; i + 1 < s.length(); ++i) {
            int c = s.charAt(i) - 'a';
            if (fl[c]++ == 0) dl++;
            if (--fr[c] == 0) dr--;
            if (dl == dr) ans++;
        }
        return ans;
    }
}

